package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class MultipleRecognitionTest {
 @Test public void allPublicNumbersAndFourBasesCheckBothDecisionsAndEveryHelpStep(){Checker c=new Checker();for(int base:List.of(15,30,45,60))for(int n=0;n<=360;n++){Question q=MultipleRecognition.make(n,base);int quotient=0;while((quotient+1)*base<=n)quotient++;int remainder=n-quotient*base;q.answers=new String[]{"poison"};q.correctChoice=999;for(String decision:List.of("0","1"))assertEquals((remainder==0?"1":"0").equals(decision),c.check(q,List.of(),List.of(decision)).correct());HelpPlan h=HelpPlan.forQuestion(q);assertEquals(4,h.size());assertFalse(h.canTransfer());assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));assertTrue(h.step(0).accepts(""+quotient));assertTrue(h.step(1).accepts(""+(base*quotient)));assertTrue(h.step(2).accepts(""+remainder));assertTrue(h.step(3).accepts(remainder==0?"1":"0"));}}
 @Test public void normalGradeSixSupplyHasFullUniqueDomainAndShuffledChoices(){String pack="na-nied-primary-2024-v1";Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,pack);assertTrue(GlobalCurriculum.pack(p).inGrade(MultipleRecognition.ID,6));assertFalse(Curriculum.inCurriculum(MultipleRecognition.SKILL,2022));Generator g=new Generator(new Random(262));List<String> recent=new ArrayList<>();Set<List<String>> orders=new HashSet<>();CurriculumLimits l=GlobalCurriculum.limits(pack,MultipleRecognition.ID,6);int positive=0,negative=0;for(int i=0;i<1444;i++){Question q=g.next(MultipleRecognition.ID,recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());orders.add(List.copyOf(q.choices));if(i<40){int[] given=MultipleRecognition.read(q);if(given[0]%given[1]==0)positive++;else negative++;}}assertTrue(positive>=8);assertTrue(negative>=8);assertTrue(orders.size()>1);assertEquals(recent.get(0),g.next(MultipleRecognition.ID,recent,false,l).signature());}
 @Test public void invalidPublicConditionsAndBlankChoiceCannotPass(){Checker c=new Checker();for(String prompt:List.of("361은 15의 배수인가요?","20은 0의 배수인가요?","30은 10의 배수인가요?","-1은 15의 배수인가요?"))assertNull(MultipleRecognition.read(new Question(MultipleRecognition.ID,prompt,"","1")));assertEquals(Checker.Status.INPUT_NEEDED,c.check(MultipleRecognition.make(360,60),List.of(),List.of("")).status);}
}
